html:
{%- from "templates/print_formats/standard_macros.html" import add_header -%}
{{ add_header(0, 1, doc, letter_head, no_letterhead, footer, print_settings) }}
<style>
.al-doc { font-size: 11px; color: #1f2933; }
.al-doc h2 { font-size: 18px; margin: 0 0 2px; letter-spacing: .02em; }
.al-doc .al-sub { color: #52606d; margin-bottom: 12px; }
.al-doc table { width: 100%; border-collapse: collapse; margin: 8px 0 12px; }
.al-doc th { background: #f0f2f5; text-align: left; font-weight: 600; }
.al-doc th, .al-doc td { border: 1px solid #cbd2d9; padding: 4px 6px; vertical-align: top; }
.al-doc .al-grid td { border: none; padding: 2px 8px 2px 0; }
.al-doc .al-label { color: #52606d; width: 22%; }
.al-doc .num { text-align: right; white-space: nowrap; }
.al-doc .al-worse { font-weight: 700; text-decoration: underline; }
.al-doc .al-sign { margin-top: 36px; }
.al-doc .al-sign td { border: none; border-top: 1px solid #52606d; width: 25%; padding-top: 4px; text-align: center; }
.al-doc .al-note { border-left: 3px solid #9aa5b1; padding: 4px 8px; color: #3e4c59; margin: 8px 0; }
</style>
<div class="al-doc">
<h2>{{ _("Equipment Gate Pass") }}</h2>
<div class="al-sub">{{ doc.name }} &middot; {{ doc.get_formatted("dispatch_datetime") }}</div>
<table class="al-grid">
<tr><td class="al-label">{{ _("Agreement") }}</td><td>{{ doc.rental_agreement }}</td><td class="al-label">{{ _("Customer") }}</td><td><b>{{ doc.customer_name }}</b></td></tr>
<tr><td class="al-label">{{ _("From yard") }}</td><td>{{ doc.from_location }}</td><td class="al-label">{{ _("To site") }}</td><td>{{ doc.to_location }}</td></tr>
<tr><td class="al-label">{{ _("Transport") }}</td><td>{{ _(doc.transport_mode) }}{% if doc.vehicle_no %} &middot; {{ doc.vehicle_no }}{% endif %}{% if doc.driver_name %} &middot; {{ doc.driver_name }}{% endif %}</td>
<td class="al-label">{{ _("LR / E-way bill") }}</td><td>{{ doc.lr_number or "-" }} / {{ doc.eway_bill_no or "-" }}</td></tr>
</table>
<table>
<tr><th>#</th><th>{{ _("Equipment") }}</th><th>{{ _("Condition out") }}</th><th class="num">{{ _("Meter out") }}</th><th class="num">{{ _("Fuel") }}</th><th>{{ _("Accessories issued") }}</th></tr>
{% for row in doc.items %}
<tr><td>{{ row.idx }}</td><td><b>{{ row.asset }}</b><br>{{ row.asset_name or "" }}</td><td>{{ _(row.condition_out) }}</td>
<td class="num">{{ row.get_formatted("meter_reading_out") if row.meter_reading_out is not none else "" }}</td>
<td class="num">{{ row.get_formatted("fuel_level_out") if row.fuel_level_out is not none else "" }}</td>
<td>{{ row.accessories or "" }}</td></tr>
{% endfor %}
</table>
{% if doc.remarks %}<div class="al-note">{{ doc.remarks }}</div>{% endif %}
<table class="al-sign"><tr><td>{{ _("Released by") }}<br>{{ frappe.db.get_value("User", doc.dispatched_by, "full_name") or "" }}</td><td>{{ _("Security") }}</td><td>{{ _("Driver") }}</td><td>{{ _("Received by") }}<br>{{ doc.received_by_name or "" }}</td></tr></table>
</div>
